import express, { NextFunction, Request, Response } from "express";
import { CreateTaskInput, TaskService } from "../application/task-service";
import { DomainError, TaskFilter, TaskStatus } from "../domain/task";
import { InMemoryTaskRepository } from "./in-memory-task-repository";

type Body = Record<string, unknown>;

function bodyOf(request: Request): Body {
  return request.body !== null && typeof request.body === "object" && !Array.isArray(request.body)
    ? (request.body as Body)
    : {};
}

function stringField(body: Body, field: string): string | undefined {
  const value = body[field];
  return typeof value === "string" ? value : undefined;
}

function statusCode(error: DomainError): number {
  return error.code === "NOT_FOUND" ? 404 : error.code === "CONFLICT" ? 409 : 400;
}

/** Creates an Express application using an isolated, in-memory data store. */
export function createApp(service = new TaskService(new InMemoryTaskRepository())) {
  const app = express();
  app.use(express.json());

  app.post("/users", (request, response) => {
    response.status(201).json(service.createUser(stringField(bodyOf(request), "name") ?? ""));
  });

  app.post("/projects", (request, response) => {
    response.status(201).json(service.createProject(stringField(bodyOf(request), "name") ?? ""));
  });

  app.post("/projects/:projectId/tasks", (request, response) => {
    const body = bodyOf(request);
    const input: CreateTaskInput = {
      title: stringField(body, "title") ?? "",
      description: stringField(body, "description") ?? "",
      ...(stringField(body, "dueDate") === undefined ? {} : { dueDate: stringField(body, "dueDate") }),
      ...(stringField(body, "status") === undefined ? {} : { status: stringField(body, "status") as TaskStatus }),
      ...(stringField(body, "assigneeId") === undefined ? {} : { assigneeId: stringField(body, "assigneeId") }),
    };
    response.status(201).json(service.createTask(request.params.projectId, input));
  });

  app.get("/projects/:projectId/tasks", (request, response) => {
    const status = typeof request.query.status === "string" ? request.query.status as TaskStatus : undefined;
    const assigneeId = typeof request.query.assigneeId === "string" ? request.query.assigneeId : undefined;
    const filter: TaskFilter = {
      ...(status === undefined ? {} : { status }),
      ...(assigneeId === undefined ? {} : { assigneeId }),
    };
    response.json(service.listTasks(request.params.projectId, filter));
  });

  app.patch("/tasks/:taskId/done", (request, response) => {
    response.json(service.markDone(request.params.taskId));
  });

  app.use((error: unknown, _request: Request, response: Response, _next: NextFunction) => {
    if (error instanceof DomainError) {
      response.status(statusCode(error)).json({ error: error.message });
      return;
    }
    response.status(500).json({ error: "Internal server error" });
  });
  return app;
}

